## The Bearer shape, for when you meet it

Most e-commerce APIs use OAuth 2.0 bearer tokens and wrap their data one level deeper. The
calls look like this — **read only, don't run it**; it's here so the shape is familiar:

```ts
// Typical bearer-token API
const res = await api.post(`${base}/api/v2/storefront/account/addresses`, {
  headers: {
    "Content-Type": "application/json",
    Authorization: `Bearer ${token}`,        // Bearer, space, token
  },
  data: { address: { firstname: "Deepika", /* ... */ } },
});

const body = await res.json();
const id = body.data.id;                      // note: wrapped in `data`
const name = body.data.attributes.firstname;  // and attributes below that
```

Two differences from Restful Booker, and both are the point:

| | Restful Booker | Bearer-style API |
|---|---|---|
| Token header | `Cookie: token=…` | `Authorization: Bearer …` |
| Reading a field | `body.firstname` | `body.data.attributes.firstname` |

Deeper nesting, same skill — walk the tree with dots, and print the body when unsure.

const patched = await api.patch(`https://restful-booker.herokuapp.com/booking/${bookingId}`, {
  headers: { "Content-Type": "application/json", Cookie: `token=${token}` },
  data: { firstname: "Patched" },          // one field only
});

const p = await patched.json();
console.log("status:   ", patched.status());
console.log("firstname:", p.firstname);      // changed
console.log("lastname: ", p.lastname);       // untouched
console.log("price:    ", p.totalprice);     // untouched

const deleted = await api.delete(`https://restful-booker.herokuapp.com/booking/${bookingId}`, {
  headers: { Cookie: `token=${token}` },
});
console.log("delete           ->", deleted.status(), await deleted.text());

const gone = await api.get(`https://restful-booker.herokuapp.com/booking/${bookingId}`);
console.log("get after delete ->", gone.status());

await api.dispose();

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because this file sits inside a template
// literal — see Day 1.1, concept 2.
const specPath = "week8/generated/day1-booking-flow.spec.ts";

await writeProjectFile(specPath, `// Week 8, Day 1 — the full booking journey against a real API.
//
// Written by a cell in week8/day1_2.ipynb. You can open, edit and run this file
// yourself:  npx playwright test week8/generated/day1-booking-flow.spec.ts
import { test, expect } from "@playwright/test";

// Restful Booker is a public practice API. The root playwright.config.ts points
// baseURL at the banking app, so every call here spells out the full URL.
const BASE = "https://restful-booker.herokuapp.com";

// Declared with \`let\`, outside the tests, because the token is created in one
// place (beforeAll) and used in another (the tests). A \`const\` inside beforeAll
// would vanish the moment that hook finished.
let token: string;
let bookingId: number;

const booking = {
  firstname: "Jim",
  lastname: "Brown",
  totalprice: 111,
  depositpaid: true,
  bookingdates: { checkin: "2018-01-01", checkout: "2019-01-01" },
  additionalneeds: "Breakfast",
};

test.describe("Booking API — the full journey", () => {
  // Each step depends on the booking the previous step made, so these must run
  // in order. Without this line Playwright would run them in parallel and they
  // would fight over the same bookingId.
  test.describe.configure({ mode: "serial" });

  test.beforeAll(async ({ request }) => {
    const res = await request.post(\`\${BASE}/auth\`, {
      data: { username: "admin", password: "password123" },
    });
    expect(res.status()).toBe(200);

    const body = await res.json();
    expect(body.token).toBeTruthy();
    token = body.token;
  });

  test("Step 1 — create a booking", async ({ request }) => {
    const res = await request.post(\`\${BASE}/booking\`, {
      headers: { "Content-Type": "application/json" },
      data: booking,
    });

    // 200, not 201 — this API returns plain OK for a create. Always check
    // rather than assuming the textbook value.
    expect(res.status()).toBe(200);

    const body = await res.json();
    expect(body.booking.firstname).toBe("Jim");

    bookingId = body.bookingid;
    expect(bookingId).toBeTruthy();
  });

  test("Step 2 — read it back", async ({ request }) => {
    const res = await request.get(\`\${BASE}/booking/\${bookingId}\`);
    expect(res.status()).toBe(200);

    const body = await res.json();
    // Note the shape changed: GET returns the booking directly, with no
    // wrapper. POST wrapped it inside \`booking\`.
    expect(body.firstname).toBe("Jim");
    expect(body.bookingdates.checkin).toBe("2018-01-01");
  });

  test("Step 3 — updating without a token is refused", async ({ request }) => {
    const res = await request.put(\`\${BASE}/booking/\${bookingId}\`, {
      data: { ...booking, firstname: "Nobody" },
    });

    // 403 Forbidden. This is what "bad credential" actually looks like.
    expect(res.status()).toBe(403);
  });

  test("Step 4 — PUT replaces the whole booking", async ({ request }) => {
    const res = await request.put(\`\${BASE}/booking/\${bookingId}\`, {
      headers: { Cookie: \`token=\${token}\` },
      data: { ...booking, firstname: "James", totalprice: 222 },
    });
    expect(res.status()).toBe(200);

    const body = await res.json();
    expect(body.firstname).toBe("James");
    expect(body.totalprice).toBe(222);
  });

  test("Step 5 — PATCH changes only what you send", async ({ request }) => {
    const res = await request.patch(\`\${BASE}/booking/\${bookingId}\`, {
      headers: { Cookie: \`token=\${token}\` },
      data: { firstname: "Patched" },
    });
    expect(res.status()).toBe(200);

    const body = await res.json();
    expect(body.firstname).toBe("Patched");
    // Untouched, because PATCH is a partial update.
    expect(body.lastname).toBe("Brown");
  });

  test("Step 6 — delete it, then prove it is gone", async ({ request }) => {
    const del = await request.delete(\`\${BASE}/booking/\${bookingId}\`, {
      headers: { Cookie: \`token=\${token}\` },
    });

    // 201 Created — an odd choice for a delete, but it is what this API does.
    expect(del.status()).toBe(201);

    const after = await request.get(\`\${BASE}/booking/\${bookingId}\`);
    expect(after.status()).toBe(404);
  });
});
`);

await runSpec(specPath);

