import type { APIRequestContext, APIResponse } from "npm:playwright";

type Booking = {
  firstname: string;
  lastname: string;
  totalprice: number;
  depositpaid: boolean;
  bookingdates: { checkin: string; checkout: string };
  additionalneeds?: string;                 // ? = optional
};

class BookingApi {
  private readonly request: APIRequestContext;
  private readonly base: string;
  private token = "";

  constructor(request: APIRequestContext, base = "https://restful-booker.herokuapp.com") {
    this.request = request;
    this.base = base;
  }

  async signIn(username = "admin", password = "password123"): Promise<void> {
    const res = await this.request.post(`${this.base}/auth`, {
      data: { username, password },
    });
    this.token = (await res.json()).token ?? "";
  }

  private authHeaders(): Record<string, string> {          // built once, not at 8 call sites
    return { "Content-Type": "application/json", Cookie: `token=${this.token}` };
  }

  create(booking: Booking): Promise<APIResponse> {
    return this.request.post(`${this.base}/booking`, {
      headers: { "Content-Type": "application/json" },
      data: booking,
    });
  }

  read(id: number): Promise<APIResponse> {
    return this.request.get(`${this.base}/booking/${id}`);
  }

  update(id: number, changes: Partial<Booking>): Promise<APIResponse> {
    return this.request.patch(`${this.base}/booking/${id}`, {
      headers: this.authHeaders(), data: changes,
    });
  }

  remove(id: number): Promise<APIResponse> {
    return this.request.delete(`${this.base}/booking/${id}`, {
      headers: this.authHeaders(),
    });
  }
}

console.log("Class defined — a shape, not a test.");

## The fixture

Building and signing in the client still has to happen somewhere. A `beforeAll` in every
spec file is the old copy-paste in a new place. A **fixture** is setup a test asks for by name:

```ts
const test = base.extend<{ api: BookingApi }>({
  api: async ({ request }, use) => {
    const api = new BookingApi(request);
    await api.signIn();     // setup
    await use(api);         // the test runs here
                            // anything after `use` would be cleanup
  },
});
```

| `beforeAll` | Fixture |
|---|---|
| runs for every test in the file | runs only for tests that ask for `api` |
| result lands in a file-level `let` | handed straight to the test |
| copy-pasted into the next file | imported |
| cleanup lives in a separate `afterAll` | cleanup sits next to its setup |

That last row matters most on a real suite: setup and teardown in one function is what stops
them drifting apart.

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because this file sits inside a template
// literal — see Day 1.1, concept 2.
const specPath = "week8/generated/day1-api-client.spec.ts";

await writeProjectFile(specPath, `// Week 8, Day 1.3 — the same calls, wrapped the way a real project wraps them.
//
// Written by a cell in week8/day1_3.ipynb. Run it yourself:
//   npx playwright test week8/generated/day1-api-client.spec.ts
import { test as base, expect, type APIRequestContext, type APIResponse } from "@playwright/test";

const BASE = "https://restful-booker.herokuapp.com";

/** The shape of a booking, written down once so every test agrees on it. */
type Booking = {
  firstname: string;
  lastname: string;
  totalprice: number;
  depositpaid: boolean;
  bookingdates: { checkin: string; checkout: string };
  additionalneeds?: string;
};

/**
 * One class per API, the same way there is one page object per screen.
 *
 * Notice what is NOT in here: not a single expect(). The client knows how to
 * make a call; the test decides whether the answer was right. That split is
 * what lets one method serve a happy-path test and a 403 test without growing
 * a second version of itself.
 */
class BookingApi {
  private readonly request: APIRequestContext;
  private readonly base: string;
  /** Filled in by signIn(). Private so a test cannot quietly corrupt it. */
  private token = "";

  constructor(request: APIRequestContext, base: string = BASE) {
    this.request = request;
    this.base = base;
  }

  /** Trades the demo credentials for a token and remembers it. */
  async signIn(username = "admin", password = "password123"): Promise<void> {
    const res = await this.request.post(\`\${this.base}/auth\`, {
      data: { username, password },
    });
    const body = await res.json();
    this.token = body.token ?? "";
  }

  /**
   * Built once here rather than at each call site, because the day this API
   * switches from a cookie to a bearer header, this is the only line to change.
   */
  private authHeaders(): Record<string, string> {
    return { "Content-Type": "application/json", Cookie: \`token=\${this.token}\` };
  }

  create(booking: Booking): Promise<APIResponse> {
    return this.request.post(\`\${this.base}/booking\`, {
      headers: { "Content-Type": "application/json" },
      data: booking,
    });
  }

  read(id: number): Promise<APIResponse> {
    return this.request.get(\`\${this.base}/booking/\${id}\`);
  }

  /** Full replace (PUT). Everything you leave out is wiped. */
  replace(id: number, booking: Booking): Promise<APIResponse> {
    return this.request.put(\`\${this.base}/booking/\${id}\`, {
      headers: this.authHeaders(),
      data: booking,
    });
  }

  /** Partial update (PATCH). Only the fields you pass are touched. */
  update(id: number, changes: Partial<Booking>): Promise<APIResponse> {
    return this.request.patch(\`\${this.base}/booking/\${id}\`, {
      headers: this.authHeaders(),
      data: changes,
    });
  }

  remove(id: number): Promise<APIResponse> {
    return this.request.delete(\`\${this.base}/booking/\${id}\`, {
      headers: this.authHeaders(),
    });
  }
}

/**
 * A fixture: setup that a test asks for by name. Every test that declares
 * \`{ api }\` gets a client that is already signed in, and no test has to
 * remember to do it.
 */
const test = base.extend<{ api: BookingApi }>({
  api: async ({ request }, use) => {
    const api = new BookingApi(request);
    await api.signIn();
    await use(api);
  },
});

const sample: Booking = {
  firstname: "Ada",
  lastname: "Lovelace",
  totalprice: 350,
  depositpaid: true,
  bookingdates: { checkin: "2024-05-01", checkout: "2024-05-08" },
  additionalneeds: "Late checkout",
};

test("a booking can be created, changed and removed", async ({ api }) => {
  // Create — the test asserts, the client does not.
  const created = await api.create(sample);
  expect(created.status()).toBe(200);
  const { bookingid: id, booking } = await created.json();
  expect(booking.firstname).toBe("Ada");

  // Partial update — lastname must survive untouched.
  const patched = await api.update(id, { firstname: "Grace" });
  expect(patched.status()).toBe(200);
  const afterPatch = await patched.json();
  expect(afterPatch.firstname).toBe("Grace");
  expect(afterPatch.lastname).toBe("Lovelace");

  // Remove, then prove it is really gone.
  expect((await api.remove(id)).status()).toBe(201);
  expect((await api.read(id)).status()).toBe(404);
});

test("a client that never signed in cannot change anything", async ({ request }) => {
  // Deliberately skipping signIn() to show what the token is actually doing.
  const anonymous = new BookingApi(request);

  const created = await anonymous.create(sample);
  expect(created.status()).toBe(200); // creating needs no token on this API

  const { bookingid: id } = await created.json();
  const blocked = await anonymous.update(id, { firstname: "Mallory" });
  expect(blocked.status()).toBe(403);
});
`);

await runSpec(specPath);
